INSERT INTO public.teacher_topic_mcqs (teacher_id,topic_key,title,questions)
SELECT 'nadia-al-nuaimy','nadia-en-ch2-lec13-exam','Topic 13 — Stratified Epithelium',$json$
[
 {"question":"Which description applies to stratified epithelium?","choices":["One row of cells with central nuclei.","One row of cells with nuclei at different levels.","Several rows of cells.","One row of cells with nuclei near the base."],"answer_index":2},
 {"question":"Stratified epithelium occurs in regions that are:","choices":["subject to friction.","specialized for diffusion and filtration.","specialized for secretion and absorption.","specialized for protection, secretion, and absorption."],"answer_index":0},
 {"question":"Why is stratified epithelium important in areas exposed to friction?","choices":["It performs diffusion and filtration in the parts it lines.","It performs secretion and absorption in the parts it covers.","It forms cilia on the parts it lines.","It protects the parts of organs that it covers or lines."],"answer_index":3},
 {"question":"Which structural feature is associated with stratified epithelium in friction-prone sites?","choices":["Its nuclei lie at different levels.","It consists of more than one row of cells.","Cilia occur on its free surface.","Its nuclei are oval and near the base."],"answer_index":1},
 {"question":"Which statement distinguishes stratified epithelium from pseudostratified columnar epithelium?","choices":["It truly consists of several rows of cells.","Its nuclei appear at different levels, suggesting several layers.","It consists of cuboidal cells with central spherical nuclei.","It consists of flat cells with central flattened nuclei."],"answer_index":0},
 {"question":"Which statement about stratified epithelium is incorrect?","choices":["It occurs in areas exposed to friction.","It protects the parts of organs it covers.","It consists of one row of cells.","It protects the parts of organs it lines."],"answer_index":2},
 {"question":"Which structure–location pairing is correct for stratified epithelium?","choices":["One row of cells — friction-prone areas.","Several rows of cells — pulmonary alveolar lining.","One row of cells — blood-vessel lining.","Several rows of cells — friction-prone areas."],"answer_index":3},
 {"question":"Which description correctly combines the structure and importance of stratified epithelium?","choices":["One row of cells; protects organ parts that it covers or lines.","Several rows of cells; protects organ parts that it covers or lines.","Several rows of cells; performs diffusion and filtration.","One row of cells; performs secretion and absorption."],"answer_index":1}
